def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def definition(text, marker, filename):
    """Extract a full unchanged definition, ignoring comment/literal braces."""
    if text.count(marker) != 1:
        raise ValueError(f'Expected one production definition: {filename}:{marker}')
    start = text.index(marker)
    opening = text.index('{', start)
    depth, end, state = 1, opening + 1, 'normal'
    while depth:
        char, pair = text[end], text[end:end + 2]
        if state == 'line':
            if char == '\n':
                state = 'normal'
        elif state == 'block':
            if pair == '*/':
                state = 'normal'
                end += 1
        elif state in ('"', "'"):
            if char == '\\':
                end += 1
            elif char == state:
                state = 'normal'
        elif pair == '//':
            state = 'line'
            end += 1
        elif pair == '/*':
            state = 'block'
            end += 1
        elif char in ('"', "'"):
            state = char
        else:
            depth += (char == '{') - (char == '}')
        end += 1
    if text[end:end + 1] == ';':
        end += 1
    line = text.count('\n', 0, start) + 1
    return f'#line {line} "{filename}"\n' + text[start:end] + '\n'

def generate(sources):
    cpp, header, menu, input_header = (sources[name].decode('utf-8') for name in ('file_io.cpp', 'file_io.h', 'menu.cpp', 'input.h'))
    if not re.search(r'^#define UPSTROKE\s+0x400000\s*$', input_header, re.MULTILINE):
        raise ValueError('Fixture UPSTROKE must equal the actual input header constant')
    extracted = {}
    def add(text, marker, filename):
        extracted[filename + ':' + marker] = definition(text, marker, filename)
    add(header, 'struct direntext_t\n', 'file_io.h')
    extracted['file_io.h:SCAN constants'] = '\n'.join(re.findall(r'^#define SCAN[FO]_[^\n]+', header, re.MULTILINE)) + '\n'
    markers = ('static int flist_last_first_entry(', 'static int flist_entry_is_expanded(',
               'static int flist_page_step(', 'static void flist_center_selected(',
               'int flist_nDirEntries(', 'int flist_iFirstEntry(', 'void flist_iFirstEntryInc(',
               'int flist_iSelectedEntry(', 'direntext_t* flist_DirItem(', 'direntext_t* flist_SelectedItem(',
               'struct DirentComp\n', 'static const char *GetRelativeFileName(',
               'static bool IsInSameFolder(', 'static void get_display_name(')
    for marker in markers:
        add(cpp, marker, 'file_io.cpp')
    private_marker = 'static bool flist_core_display_initial_matches('
    if private_marker in cpp:
        add(cpp, private_marker, 'file_io.cpp')
    add(cpp, 'int ScanDirectory(', 'file_io.cpp')
    typed_marker = '\n\t\t\t{\n\t\t\t\tchar i;\n\t\t\t\tif ((i = GetASCIIKey(c)) > 1)'
    typed = definition(menu, typed_marker, 'menu.cpp')
    start = menu.index(typed_marker) + 1
    extracted['menu.cpp:HandleUI typed-input local scope'] = f'#line {menu.count(chr(10), 0, start) + 1} "menu.cpp"\n' + typed.split('\n', 1)[1][1:]
    key_start = menu.index('static const uint8_t keycode_table[128]')
    key_end = menu.index('};', key_start) + 2
    extracted['menu.cpp:keycode_table'] = menu[key_start:key_end] + '\n'
    for marker in ('static uint8_t GetASCIIKey(', 'void ScrollLongName(void)', 'void PrintDirectory(int expand)'):
        add(menu, marker, 'menu.cpp')
    types = extracted['file_io.h:struct direntext_t\n'] + extracted['file_io.h:SCAN constants']
    production = ''
    for key, body in extracted.items():
        if not key.startswith('file_io.cpp:') or key == 'file_io.cpp:int ScanDirectory(':
            continue
        if key == 'file_io.cpp:static void flist_center_selected(':
            production += '#define flist_center_selected production_flist_center_selected\n' + body + '#undef flist_center_selected\n'
            production += 'static void flist_center_selected() { ++center_calls; production_flist_center_selected(); }\n'
        else:
            production += body
    production += '#define ScanDirectory production_scan_directory\n' + extracted['file_io.cpp:int ScanDirectory('] + '#undef ScanDirectory\n'
    production += '''int ScanDirectory(char *path, int mode, const char *extension, int options, const char *prefix, const char *filter_value)
{
    queries.push_back("ScanDirectory.begin:mode=" + std::to_string(mode) + ":options=" + std::to_string(options) + ":filter=" + (filter_value ? filter_value : "<null>"));
    int result = production_scan_directory(path, mode, extension, options, prefix, filter_value);
    queries.push_back("ScanDirectory.end:return=" + std::to_string(result) + ":count=" + std::to_string(DirItem.size()) + ":selected=" + std::to_string(iSelectedEntry));
    return result;
}
'''
    production += extracted['menu.cpp:keycode_table'] + extracted['menu.cpp:static uint8_t GetASCIIKey(']
    production += 'static void typed_event(uint32_t c)\n{\n' + extracted['menu.cpp:HandleUI typed-input local scope'] + '}\n'
    production += extracted['menu.cpp:void ScrollLongName(void)'] + extracted['menu.cpp:void PrintDirectory(int expand)']
    return types, production, extracted

